let data = load(); let selectedClass = data.classes.includes(data.selectedClass) ? data.selectedClass : data.classes[0]; let draftImport = []; let draftCalendarImport = []; let sourceObjectUrls = {};
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? "").replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
