function saveSetup() { data.setup.termName = $("#termName").value.trim() || "未命名學年"; data.setup.cycleStart = $("#cycleStart").value; data.setup.cycleEnd = $("#cycleEnd").value; data.setup.cycleLength = Number($("#cycleLength").value); data.excludedRanges = [...document.querySelectorAll(".calendar-entry")].map(row => ({ start: row.querySelector('[data-field="start"]').value, end: row.querySelector('[data-field="end"]').value, note: row.querySelector('[data-field="note"]').value.trim(), source: row.dataset.source || "手動" })).filter(entry => entry.start && (!entry.end || entry.end >= entry.start)); save(); renderSetup(); renderTimetable(); renderToday(); }
function saveTimetable() { ["morning", "afternoon"].forEach(section => { data[`${section}Periods`] = [...document.querySelectorAll(`.period-row[data-section="${section}"]`)].map(row => ({ name: row.querySelector('[data-period-field="name"]').value.trim() || "未命名節次", start: row.querySelector('[data-period-field="start"]').value, end: row.querySelector('[data-period-field="end"]').value })); }); data.blocks = [...document.querySelectorAll(".block-row")].map(row => ({ section: row.querySelector('[data-block-field="section"]').value, after: Number(row.querySelector('[data-block-field="after"]').value), label: row.querySelector('[data-block-field="label"]').value.trim(), start: row.querySelector('[data-block-field="start"]').value, end: row.querySelector('[data-block-field="end"]').value })).filter(block => block.label); data.lessons[selectedClass] = {}; document.querySelectorAll(".slot").forEach(slot => { const entry = { subject: slot.querySelector('[data-slot-field="subject"]').value.trim(), room: slot.querySelector('[data-slot-field="room"]').value.trim() }; if (entry.subject || entry.room) data.lessons[selectedClass][`${slot.dataset.section}-${slot.dataset.day}-${slot.dataset.period}`] = entry; }); save(); renderTimetable(); renderToday(); }

function parseCycle(value) { const text = String(value ?? "").toUpperCase(); const letter = text.match(/DAY\s*([A-Z])/)?.[1] || text.match(/^\s*([A-Z])\s*$/)?.[1]; const day = letter ? letter.charCodeAt(0) - 64 : Number(text.match(/\d+/)?.[0]); return cycleDays().includes(day) ? day : null; }
