function previewImport() { const message = $("#importMessage"); try { const parsed = JSON.parse($("#recognitionJson").value); if (!Array.isArray(parsed)) throw new Error("辨認結果必須是一組課節資料。"); draftImport = parsed.map((row, index) => { const section = /week|afternoon|下午|星期/.test(String(row.section || row.day || row.weekday || "").toLowerCase()) ? "afternoon" : "morning"; const day = section === "morning" ? parseCycle(row.day ?? row.cycleDay) : parseWeekday(row.day ?? row.weekday); return { page: Math.max(1, Number(row.page) || 1), section, day, period: parsePeriod(row.period, section), subject: String(row.subject || ""), room: String(row.room || ""), confidence: Number(row.confidence ?? .75), index }; }).filter(row => row.day !== null && row.period >= 0 && row.subject); if (!draftImport.length) throw new Error("找不到可匯入的課節；請檢查上午／下午、日期欄、節次和科目。"); const pages = new Set(draftImport.map(row => row.page)).size; message.textContent = `已建立 ${draftImport.length} 個課節、${pages} 頁來源的核對預覽。請修正黃色列後再確認匯入。`; message.className = "import-message success"; renderImportPreview(); } catch (error) { draftImport = []; $("#importPreview").innerHTML = ""; message.textContent = error.message || "無法讀取辨認結果。"; message.className = "import-message"; } }
function renderImportPreview() { const dayOptions = section => (section === "morning" ? cycleDays().map(day => ({ value: day, label: cycleLabel(day) })) : WEEKDAYS.map((label, index) => ({ value: index, label }))); $("#importPreview").innerHTML = `<table><thead><tr><th>來源頁</th><th>時段</th><th>日期欄</th><th>節次</th><th>科目</th><th>課室／備註</th><th>辨認信心</th></tr></thead><tbody>${draftImport.map((row, index) => `<tr class="${row.confidence < .8 ? "confidence-low" : ""}" data-import-row="${index}"><td>第 ${row.page} 頁</td><td>${row.section === "morning" ? "上午循環日" : "下午星期"}</td><td><select data-import-field="day">${dayOptions(row.section).map(option => `<option value="${option.value}" ${Number(option.value) === row.day ? "selected" : ""}>${option.label}</option>`).join("")}</select></td><td><select data-import-field="period">${data[`${row.section}Periods`].map((period, periodIndex) => `<option value="${periodIndex}" ${periodIndex === row.period ? "selected" : ""}>${esc(period.name)} (${period.start})</option>`).join("")}</select></td><td><input data-import-field="subject" value="${esc(row.subject)}"/></td><td><input data-import-field="room" value="${esc(row.room)}"/></td><td class="${row.confidence < .8 ? "" : "confidence-high"}">${Math.round(row.confidence * 100)}%</td></tr>`).join("")}</tbody></table>`; }
