function previewCalendarImport() { const message = $("#calendarImportMessage"); try { const parsed = JSON.parse($("#calendarRecognitionJson").value); if (!Array.isArray(parsed)) throw new Error("校曆辨認結果必須是一組日期資料。"); draftCalendarImport = parsed.map((row, index) => ({ date: parseCalendarDate(row.date), note: String(row.note || row.summary || "不適用日"), source: "辨認結果", confidence: Number(row.confidence ?? .75), index })).filter(row => row.date); if (!draftCalendarImport.length) throw new Error("找不到有效日期；請使用 YYYY-MM-DD 格式。 "); const uncertain = draftCalendarImport.filter(row => row.confidence < .8).length; message.textContent = `已建立 ${draftCalendarImport.length} 個不適用日期的核對預覽${uncertain ? `，其中 ${uncertain} 個需要核對` : ""}。`; message.className = "import-message success"; renderCalendarImportPreview(); } catch (error) { draftCalendarImport = []; $("#calendarImportPreview").innerHTML = ""; message.textContent = error.message || "無法讀取校曆辨認結果。"; message.className = "import-message"; } }
function applyCalendarImport() { if (!draftCalendarImport.length) { $("#calendarImportMessage").textContent = "請先建立逐日核對預覽。"; return; } const excluded = new Map(data.excludedRanges.map(entry => [`${entry.start}/${entry.end || ""}`, entry])); const holidays = new Map((data.publicHolidays || []).map(entry => [`${entry.start}/${entry.end || ""}`, entry])); document.querySelectorAll("[data-calendar-import-row]").forEach(row => { const date = row.querySelector('[data-calendar-import-field="date"]').value; if (!date) return; const draft = draftCalendarImport[Number(row.dataset.calendarImportRow)]; const entry = { start: date, end: "", note: row.querySelector('[data-calendar-import-field="note"]').value.trim() || "不適用日", source: draft.source }; (draft.source === "公眾假期 JSON" ? holidays : excluded).set(`${date}/`, entry); }); data.excludedRanges = [...excluded.values()].sort((a, b) => a.start.localeCompare(b.start)); data.publicHolidays = [...holidays.values()].sort((a, b) => a.start.localeCompare(b.start)); save(); const publicCount = draftCalendarImport.filter(row => row.source === "公眾假期 JSON").length; $("#calendarImportMessage").textContent = publicCount === draftCalendarImport.length ? `已把 ${publicCount} 個公眾假期套用至右側校曆。` : `已匯入 ${draftCalendarImport.length} 個校曆日期。`; $("#calendarImportMessage").className = "import-message success"; renderSetup(); renderToday(); }
function compactDate(value) { const text = Array.isArray(value) ? value[0] : value; return typeof text === "string" && /^\d{8}$/.test(text) ? `${text.slice(0, 4)}-${text.slice(4, 6)}-${text.slice(6, 8)}` : parseCalendarDate(text); }
function dateRange(start, end) { const first = localDate(start); const last = end ? localDate(end) : new Date(first); last.setDate(last.getDate() - (end ? 1 : 0)); const dates = []; while (first <= last) { dates.push(iso(first)); first.setDate(first.getDate() + 1); } return dates; }
async function importPublicHolidayJSON(file) { const message = $("#calendarImportMessage"); try { const payload = JSON.parse((await file.text()).replace(/^\uFEFF/, "")); const events = payload.vcalendar?.flatMap(calendar => calendar.vevent || []) || []; draftCalendarImport = events.flatMap(event => dateRange(compactDate(event.dtstart), compactDate(event.dtend)).map(date => ({ date, note: `公眾假期：${event.summary || "未命名"}`, source: "公眾假期 JSON", confidence: 1 }))).filter(entry => entry.date && withinCycleRange(entry.date)); if (!draftCalendarImport.length) throw new Error("JSON 內沒有找到循環周期間的公眾假期日期。"); $("#calendarSourceLabel").textContent = `已讀取：${file.name}`; message.textContent = `已從 JSON 找到 ${draftCalendarImport.length} 個循環周期間的公眾假期日期，請核對後匯入。`; message.className = "import-message success"; renderCalendarImportPreview(); } catch (error) { message.textContent = error.message || "無法讀取公眾假期 JSON。"; message.className = "import-message"; } }
function loadCalendarSample() { $("#calendarRecognitionJson").value = JSON.stringify([{ date: "2026-10-02", note: "學校假期", confidence: .88 }, { date: "2026-11-13", note: "校內活動", confidence: .76 }], null, 2); previewCalendarImport(); }
function previewSource(file, labelSelector, previewSelector, description) { const label = $(labelSelector); const preview = $(previewSelector); if (sourceObjectUrls[previewSelector]) URL.revokeObjectURL(sourceObjectUrls[previewSelector]); sourceObjectUrls[previewSelector] = ""; preview.hidden = true; preview.innerHTML = ""; if (!file) { label.textContent = "拍攝、上載圖片或 PDF"; return; } const isPDF = file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf"); const isImage = file.type.startsWith("image/"); if (!isPDF && !isImage) { label.textContent = "不支援此檔案類型"; return; } const source = URL.createObjectURL(file); sourceObjectUrls[previewSelector] = source; label.textContent = `已選擇：${file.name}`; preview.hidden = false; preview.innerHTML = isPDF ? `<p>已載入 PDF：${esc(file.name)}。${description}</p><object data="${source}" type="application/pdf" aria-label="已上載的 PDF"></object>` : `<p>已載入圖片：${esc(file.name)}。${description}</p><img src="${source}" alt="已上載的圖片預覽" />`; }
function loadSample() { $("#recognitionJson").value = JSON.stringify([{ page: 1, section: "cycle", day: "Day A", period: "第 1 節", subject: "中文", room: "201", confidence: .96 }, { page: 1, section: "cycle", day: "Day C", period: "第 3 節", subject: "中默", room: "201", confidence: .91 }, { page: 2, section: "afternoon", day: "星期一", period: "第 7 節", subject: "常識", room: "201", confidence: .63 }], null, 2); previewImport(); }
function showTab(tab) { $("#setupPanel").hidden = tab !== "setup"; $("#calendarImportPanel").hidden = tab !== "calendar-import"; $("#timetablePanel").hidden = tab !== "timetable"; $("#importPanel").hidden = tab !== "import"; document.querySelectorAll("[data-tab]").forEach(button => button.classList.toggle("active", button.dataset.tab === tab)); }
document.addEventListener("click", event => { const button = event.target.closest("[data-action]"); if (!button) return; const action = button.dataset.action; if (action === "return-home") { window.location.href = button.dataset.homeUrl; return; }
  if (action === "save-setup") saveSetup(); if (action === "save-timetable") saveTimetable(); if (action === "add-calendar-entry") { data.excludedRanges.push({ start: "", end: "", note: "", source: "手動" }); renderExcludedDates(); } if (action === "remove-calendar-entry") { data.excludedRanges.splice(Number(button.closest(".calendar-entry").dataset.index), 1); renderExcludedDates(); }
  if (action === "previous-month" || action === "next-month") { const date = new Date(`${data.calendarMonth}-01T12:00:00`); date.setMonth(date.getMonth() + (action === "next-month" ? 1 : -1)); data.calendarMonth = iso(date).slice(0, 7); renderCalendar(); }
  if (action === "add-class") { const name = prompt("新班別名稱，例如：4A"); if (name?.trim() && !data.classes.includes(name.trim())) { data.classes.push(name.trim()); data.lessons[name.trim()] = {}; selectedClass = name.trim(); save(); renderTimetable(); renderToday(); } }
  if (action === "add-morning-period" || action === "add-afternoon-period") { const section = action.includes("morning") ? "morning" : "afternoon"; data[`${section}Periods`].push({ name: `第 ${data[`${section}Periods`].length + (section === "afternoon" ? 7 : 1)} 節`, start: "", end: "" }); renderTimetable(); }
  if (action === "remove-period") { const row = button.closest(".period-row"); data[`${row.dataset.section}Periods`].splice(Number(row.dataset.period), 1); renderTimetable(); } if (action === "add-block") { data.blocks.push({ section: "morning", after: -1, label: "固定時段", start: "", end: "" }); renderBlocks(); } if (action === "remove-block") { data.blocks.splice(Number(button.closest(".block-row").dataset.block), 1); renderBlocks(); }
  if (action === "preview-import") previewImport(); if (action === "apply-import") applyImport(); if (action === "load-sample") loadSample(); if (action === "preview-calendar-import") previewCalendarImport(); if (action === "apply-calendar-import") applyCalendarImport(); if (action === "load-calendar-sample") loadCalendarSample(); if (action === "jump-timetable") showTab("timetable");
});
document.addEventListener("change", event => { if (event.target.id === "classSelect") { selectedClass = event.target.value; data.selectedClass = selectedClass; save(); renderTimetable(); renderToday(); } if (event.target.id === "sourceInput") previewSource(event.target.files[0], "#sourceLabel", "#sourcePreview", "辨認結果會顯示於下方草稿。"); if (event.target.id === "calendarSourceInput") { const file = event.target.files[0]; if (file && (file.type === "application/json" || file.name.toLowerCase().endsWith(".json"))) importPublicHolidayJSON(file); else previewSource(file, "#calendarSourceLabel", "#calendarSourcePreview", "辨認服務接入後會擷取不適用日期並建立核對草稿。"); } });
document.querySelectorAll("[data-tab]").forEach(button => button.addEventListener("click", () => showTab(button.dataset.tab)));
renderSetup(); renderTimetable(); renderToday();
window.addEventListener("teacher-data-reloaded", () => {
  data = load(); selectedClass = data.selectedClass || data.classes[0]; renderSetup(); renderTimetable(); renderToday();
});
